//! Static Linux syscall name-to-number tables for `Syscall::Named` policy
//! rules. Generated from seccompiler 0.5.0's auto-generated tables (kernel
//! 6.12); only names present on both x86_64 and aarch64 are exposed, and each
//! name resolves to the number for the *current* target architecture.

/// Resolve a syscall name to its number on this target architecture.
pub fn syscall_number(name: &str) -> Option<i64> {
    SYSCALL_NUMBERS
        .binary_search_by(|(known, _)| (*known).cmp(name))
        .ok()
        .map(|index| SYSCALL_NUMBERS[index].1)
}

