#[cfg(test)]
mod tests {
    #[test]
    fn common_names_resolve() {
        assert!(super::syscall_number("read").is_some());
        assert!(super::syscall_number("openat").is_some());
        assert!(super::syscall_number("execve").is_some());
        assert_eq!(super::syscall_number("definitely_not_a_syscall"), None);
    }
}
